				console.log('[UP:END]', {
					firstAddress: pageContext.addresses?.[0]?.concatenated_address,
					lastAddress: pageContext.addresses?.[119]?.concatenated_address,
					firstIndex: pageContext.allAddressesFirstIndex,
					lastIndex: pageContext.allAddressesLastIndex,
					domCount: pageContext.addresses?.length,
					scrollTop: scrollEl.scrollTop,
				});

